def get_total_number_of_sequences(m, n):
    # Initialize a 2D list to store the number of sequences for each pair of (i, j)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: There is one way to form a sequence of length 0 with any number
    for i in range(m + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            # The number of sequences ending with i is the sum of sequences ending with i/2 and i/3
            dp[i][j] = dp[i // 2][j - 1] + dp[i // 3][j - 1]

    # The answer is the number of sequences of length n that can be formed with any number
    return dp[m][n]

