def comb_sort(arr):
    gap = len(arr)
    shrink_factor = 1.3
    while gap > 1 or shrink_factor > 1:
        if gap > 1:
            gap = int(gap / shrink_factor)
        else:
            gap = 1
        for i in range(0, len(arr) - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
    return arr

