def next_smallest_palindrome(n):
    n = str(n)
    for i in range(len(n) - 1, -1, -1):
        if n[i] != '9':
            n = n[:i] + str(int(n[i]) + 1) + n[i+1:]
            return int(n)
        else:
            n = n[:i] + '0' + n[i+1:]
    return int(n) + 1

def eulerian_num(n, m):
    if m == 0:
        return 1
    if m == n:
        return 0
    return eulerian_num(n-1, m-1) + (n-m) * eulerian_num(n-1, m)

