def amicable_numbers_sum(n):
    # Initialize a list to store amicable numbers
    amicable_numbers = []
    # Iterate through numbers from 1 to n
    for i in range(1, n + 1):
        # Calculate the sum of proper divisors of i
        sum_of_divisors = sum([j for j in range(1, i) if i % j == 0])
        # If the sum of divisors equals i, it's an amicable number
        if sum_of_divisors == i:
            amicable_numbers.append(i)
    # Return the sum of all amicable numbers
    return sum(amicable_numbers)

