def magic_square_test(matrix):
    # Check if the matrix is square
    if len(matrix) != len(matrix[0]):
        return False

    # Calculate the sum of the first row
    sum_row = sum(matrix[0])

    # Check if the sum of each row is equal to the sum of the first row
    for row in matrix:
        if sum(row) != sum_row:
            return False

    # Check if the sum of each column is equal to the sum of the first row
    for i in range(len(matrix)):
        column_sum = sum(matrix[j][i] for j in range(len(matrix)))
        if column_sum != sum_row:
            return False

    # Check if the sum of the main diagonal is equal to the sum of the first row
    main_diagonal_sum = sum(matrix[i][i] for i in range(len(matrix)))
    if main_diagonal_sum != sum_row:
        return False

    # Check if the sum of the secondary diagonal is equal to the sum of the first row
    secondary_diagonal_sum = sum(matrix[i][len(matrix)-1-i] for i in range(len(matrix)))
    if secondary_diagonal_sum != sum_row:
        return False

    return True

def reverse_vowels(s):
    vowels = 'aeiouAEIOU'
    s = list(s)
    i = 0
    j = len(s) - 1
    while i < j:
        if s[i] not in vowels:
            i += 1
        elif s[j] not in vowels:
            j -= 1
        else:
            s[i], s[j] = s[j], s[i]
            i += 1
            j -= 1
    return ''.join(s)

def check():
