def max_sum(arr):
    n = len(arr)
    # Initialize the dp arrays for increasing and decreasing subsequences
    dp_inc = [1] * n
    dp_dec = [1] * n
    max_sum = 0

    # Fill the dp arrays for increasing subsequences
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp_inc[i] = max(dp_inc[i], dp_inc[j] + 1)

    # Fill the dp arrays for decreasing subsequences
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                dp_dec[i] = max(dp_dec[i], dp_dec[j] + 1)

    # Find the maximum sum of a bitonic subsequence
    for i in range(n):
        max_sum = max(max_sum, dp_inc[i] + dp_dec[i] - 1)

    return max_sum

import math


def babylonian_squareroot(n):
    """
    Compute the square root of a number using the Babylonian method.
    """
    if n < 0:
        raise ValueError("Cannot compute the square root of a negative number.")
    if n == 0:
        return 0
    guess = n / 2.0
    while True:
        next_guess = (guess + n / guess) / 2.0
        if abs(next_guess - guess) < 1e-6:
            break
        guess = next_guess
    return guess

def lps(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])
    return dp[0][n - 1]

