    # Initialize a dictionary to store the maximum aggregate for each name
    max_aggregate_dict = {}
    for name, score in test_list:
        # If the name is already in the dictionary, update the maximum aggregate
        if name in max_aggregate_dict:
            max_aggregate_dict[name] = max(max_aggregate_dict[name], score)
        # If the name is not in the dictionary, add it with the score as the maximum aggregate
        else:
            max_aggregate_dict[name] = score
    # Find the name with the maximum aggregate
    max_aggregate_name = max(max_aggregate_dict, key=max_aggregate_dict.get)
