    left = 0
    right = len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        # Check if the middle element is odd or even
        if mid % 2 == 0:
            # If the element at mid and mid+1 are the same, the single element must be on the right side
            if arr[mid] == arr[mid + 1]:
                left = mid + 2
            else:
                right = mid
        else:
            # If the element at mid and mid-1 are the same, the single element must be on the left side
