def newman_prime(n):
    # Initialize the list of primes with the first few Newman-Shanks-Williams primes
    primes = [2, 11, 41]

    # Function to check if a number is prime
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Generate more primes until we reach the nth one
    while len(primes) < n:
        # Calculate the next Newman-Shanks-Williams prime
        next_prime = 4 * primes[-1] - primes[-2] + 1

        # Check if the next prime is not already in the list and is prime
        if next_prime not in primes and is_prime(next_prime):
            primes.append(next_prime)

    # Return the nth Newman-Shanks-Williams prime
    return primes[n-1]

