def is_magic_square(matrix):
    n = len(matrix)
    if n == 0:
        return False
    # 检查行和
    for i in range(n):
        if sum(matrix[i]) != sum(matrix[0]):
            return False
    # 检查列和
    for j in range(n):
        if sum(matrix[i][j] for i in range(n)) != sum(matrix[0][j]):
            return False
    # 检查对角线和
    if sum(matrix[i][i] for i in range(n)) != sum(matrix[i][n-i-1] for i in range(n)):
        return False
    if sum(matrix[i][n-i-1] for i in range(n)) != sum(matrix[i][i] for i in range(n)):
        return False
    return True

