def max_product_in_subsequence(arr):
    if len(arr) == 0:
        return 0
    if len(arr) == 1:
        return arr[0]

    max_product = arr[0]
    min_product = arr[0]
    left_max = arr[0]
    left_min = arr[0]

    for i in range(1, len(arr)):
        if arr[i] > arr[i-1]:
            left_max = max(left_max * arr[i], arr[i])
            left_min = min(left_min * arr[i], arr[i])
        else:
            left_max = max(left_max * arr[i], arr[i])
            left_min = min(left_min * arr[i], arr[i])

        max_product = max(max_product, left_max * left_min)

    return max_product

